def semver_sort(versions):
    def parse_version(version_str):
        # Split by '+' to separate build metadata
        parts = version_str.split('+')
        version_without_build = parts[0]

        # Split by '-' to separate pre-release, but keep the main version intact
        if '-' in version_without_build:
            idx = version_without_build.index('-')
            main_version = version_without_build[:idx]
            pre_release = version_without_build[idx+1:]
        else:
            main_version = version_without_build
            pre_release = None

        # Parse MAJOR.MINOR.PATCH
        version_parts = main_version.split('.')
        major = int(version_parts[0])
        minor = int(version_parts[1])
        patch = int(version_parts[2])

        # Parse pre-release identifiers
        pre_release_identifiers = None
        if pre_release:
            identifiers = pre_release.split('.')
            pre_release_identifiers = []
            for identifier in identifiers:
                if identifier.isdigit():
                    pre_release_identifiers.append((0, int(identifier)))
                else:
                    pre_release_identifiers.append((1, identifier))

        return (major, minor, patch, pre_release_identifiers)

    def compare_pre_release(pre1, pre2):
        # If both have no pre-release, they're equal (based on precedence, not input order)
        if pre1 is None and pre2 is None:
            return 0

        # A version with a pre-release has lower precedence than without
        if pre1 is None:
            return 1
        if pre2 is None:
            return -1

        # Compare identifiers left to right
        for i in range(min(len(pre1), len(pre2))):
            type1, val1 = pre1[i]
            type2, val2 = pre2[i]

            # All-digit identifier sorts before any other identifier
            if type1 != type2:
                return type1 - type2

            # Same type: compare numerically or lexically
            if val1 < val2:
                return -1
            elif val1 > val2:
                return 1

        # If every shared identifier is equal, fewer identifiers sorts first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1

        return 0

    # Parse all versions
    parsed = []
    for i, version_str in enumerate(versions):
        parsed_version = parse_version(version_str)
        parsed.append((parsed_version, i, version_str))

    # Sort by parsed version, then by input order for equal precedence
    def sort_key(item):
        parsed_version, original_index, _ = item
        major, minor, patch, pre_release = parsed_version
        # Return tuple for sorting: (major, minor, patch, pre_release_sort_key, original_index)
        # For pre_release, we need a sortable key
        if pre_release is None:
            pre_release_key = (1,)  # Higher than any pre-release
        else:
            pre_release_key = (0, pre_release)

        return (major, minor, patch, pre_release_key, original_index)

    sorted_items = sorted(parsed, key=sort_key)
    return [item[2] for item in sorted_items]

